def compute_atr(bars, period=14):
    if not bars or len(bars) < period: return 0.0
    tr_values = []; prev_close = None
    for h, l, c in bars:
        tr = h - l if prev_close is None else max(h-l, abs(h-prev_close), abs(l-prev_close))
        tr_values.append(tr); prev_close = c
    atr = sum(tr_values[:period]) / period
    for tr in tr_values[period:]:
        atr = ((atr * (period - 1)) + tr) / period
    return atr

def apply_dynamic_exit(entry_price, atr, multiplier=1.5):
    band = atr * multiplier
    return {'stop': entry_price - band, 'take_profit': entry_price + band}

def diff_snapshots(owner, old_ts, new_ts):
    import hashlib
    old = SNAP_ROOT / owner / old_ts
    new = SNAP_ROOT / owner / new_ts
    if not old.exists() or not new.exists():
        return {"added": [], "removed": [], "modified": [], "error": "missing snapshot"}
    def hashes(root):
        out = {}
        for p in root.rglob("*"):
            if p.is_file():
                rel = str(p.relative_to(root))
                out[rel] = hashlib.sha256(p.read_bytes()).hexdigest()
        return out
    a, b = hashes(old), hashes(new)
    added = sorted(set(b) - set(a))
    removed = sorted(set(a) - set(b))
    modified = sorted(k for k in set(a) & set(b) if a[k] != b[k])
    return {"added": added, "removed": removed, "modified": modified}
